# anime-whisper CT2 crashes on long single-pass media (Windows 0xC0000005).
# Keep each extract/window under this span; proven safe around ≤3–5 min.
_WINDOWED_MAX_SPAN_S = 180.0
_WINDOWED_PAD_S = 0.35
_WINDOWED_CLIP_MERGE_GAP_S = 0.75
_WINDOWED_FIXED_OVERLAP_S = 0.75

# anime-whisper TEN VAD preset: VAD owns the timeline.
# Tighter than the looser 1.0s / 6.0s grouping so cues stay short.
_ANIME_VAD_CHUNK_THRESHOLD_S = 0.5
_ANIME_VAD_MAX_GROUP_S = 5.0
_ANIME_VAD_MIN_ISLAND_S = 0.22
_ANIME_VAD_MERGE_GAP_S = 0.5
_ANIME_FRAME_CHAR_CHUNK = 10

_SENTENCE_END = set("。！？!?．.｡")
_CLAUSE_BREAK = set("、，,;； ")
_WORD_GAP_BREAK_S = 0.45
# English / Latin dialogue pauses are longer than JA; 0.45s over-fragmented
# Spider-Verse opening monologue into word islands.
_WORD_GAP_BREAK_S_LATIN = 0.85
_MAX_CUE_DURATION_S = 6.5
_MAX_CJK_CHARS = 28
_MAX_LATIN_CHARS = 56
_FUZZY_MIN_SIM = 0.38
_FUZZY_LOOKAHEAD = 14

# Whisper BPE / tokenizer debris + Latin spacing quirks
_BPE_MARK = "\u2581"  # ▁
_APOS_SPACE = re.compile(
    r"\b([A-Za-z]+)\s+'\s*([A-Za-z]+)\b"
)
_APOS_SUFFIXES = frozenset({"m", "s", "re", "ve", "ll", "d", "t", "am", "em"})
_DIGIT_PAIR = re.compile(r"(?<!\d)(\d)\s+(\d)(?!\d)")
_CAMEL_GLUE = re.compile(r"([a-z])([A-Z])")
_SPACE_BEFORE_PUNCT = re.compile(r"\s+([,.!?;:])")
_MULTI_WS = re.compile(r"[ \t\u3000]+")
_MATCH_PUNCT = re.compile(
    r"[\s\u3000、。！？!?…・\.\,，．｡『』「」\"'“”‘’（）\(\)【】\[\]~～ー−\-]+"
)


def normalize_whisper_text(text: str) -> str:
    """Normalize Latin Whisper artifacts (▁, spaced apostrophes, digit splits)."""
    s = str(text or "")
    if not s:
        return ""
    if _BPE_MARK in s:
        s = s.replace(_BPE_MARK, " ")

    def _apos(m: re.Match[str]) -> str:
        left, right = m.group(1), m.group(2)
        # don ' t / I ' m / let ' s → don't / I'm / let's
        # but I ' been (missing ve) → "I been", not "I'been"
        if right.lower() in _APOS_SUFFIXES or len(right) <= 2:
            return f"{left}'{right}"
        return f"{left} {right}"

    for _ in range(3):
        nxt = _APOS_SPACE.sub(_apos, s)
        if nxt == s:
            break
        s = nxt
    # and for 1 0 years → and for 10 years (single-digit pairs only)
    for _ in range(4):
        nxt = _DIGIT_PAIR.sub(r"\1\2", s)
        if nxt == s:
            break
        s = nxt
    s = _CAMEL_GLUE.sub(r"\1 \2", s)
    s = _SPACE_BEFORE_PUNCT.sub(r"\1", s)
    s = _MULTI_WS.sub(" ", s).strip()
    return s


# Process-level WhisperModel cache (cleared by release_gpu_memory).
_MODEL_CACHE: dict[str, Any] = {}


def clear_model_cache() -> int:
    """Drop cached WhisperModel instances so GC can free VRAM."""
    n = len(_MODEL_CACHE)
    _MODEL_CACHE.clear()
    try:
        import gc

        gc.collect()
    except Exception:
        pass
    try:
        import torch  # type: ignore

        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass
    return n


def _get_cached_whisper_model(
    WhisperModel: Any,
    model_dir: str,
    *,
    device: str,
    compute_type: str,
) -> Any:
    key = f"{model_dir}|{device}|{compute_type}"
    cached = _MODEL_CACHE.get(key)
    if cached is not None:
        return cached
    model = WhisperModel(model_dir, device=device, compute_type=compute_type)
    _MODEL_CACHE[key] = model
    return model


def _probe_duration_s(media_path: str) -> float:
    path = Path(media_path)
    suffix = path.suffix.lower()
    if suffix == ".wav":
        try:
            import wave

            with wave.open(str(path), "rb") as wf:
                frames = wf.getnframes()
                rate = wf.getframerate() or 16000
                return max(0.0, float(frames) / float(rate))
        except Exception:
            return 0.0
    try:
        from ..ffmpeg_util import resolve_ffprobe
        import json
        import subprocess
        import os

        ffprobe = resolve_ffprobe()
        if not ffprobe:
            return 0.0
        cmd = [
            ffprobe,
            "-v",
            "error",
            "-show_entries",
            "format=duration",
            "-of",
            "json",
            str(path),
        ]
        run_kwargs: dict[str, Any] = {
            "capture_output": True,
            "text": True,
            "encoding": "utf-8",
            "errors": "replace",
            "check": False,
        }
        if os.name == "nt":
            run_kwargs["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        proc = subprocess.run(cmd, **run_kwargs)
        if proc.returncode != 0:
            return 0.0
        data = json.loads(proc.stdout or "{}")
        return max(0.0, float((data.get("format") or {}).get("duration") or 0))
    except Exception:
        return 0.0


def _is_cjk_script_char(ch: str) -> bool:
    if not ch:
        return False
    o = ord(ch)
    return (
        0x4E00 <= o <= 0x9FFF
        or 0x3040 <= o <= 0x309F
        or 0x30A0 <= o <= 0x30FF
        or 0x3400 <= o <= 0x4DBF
        or 0xF900 <= o <= 0xFAFF
        or 0xFF66 <= o <= 0xFF9D
    )


def _display_len(text: str) -> int:
    return len(re.sub(r"\s+", "", str(text or "")))


def _is_cjk_heavy(text: str) -> bool:
    raw = re.sub(r"\s+", "", str(text or ""))
    if not raw:
        return False
    cjk = sum(1 for ch in raw if _is_cjk_script_char(ch))
    return (cjk / max(len(raw), 1)) >= 0.25


def _join_whisper_words(tokens: list[str]) -> str:
    if not tokens:
        return ""
    raw = "".join(tokens)
    if _is_cjk_heavy(raw):
        return re.sub(r"\s+", "", raw).strip()
    # Whisper Latin tokens usually include a leading space (" hello").
    # If tokens were stripped (or the backend omits the marker), insert spaces.
    if any(str(t).startswith((" ", "\t", "\u3000")) for t in tokens):
        out = "".join(tokens)
    else:
        pieces: list[str] = []
        for t in tokens:
            bare = str(t or "").strip()
            if not bare:
                continue
            if not pieces:
                pieces.append(bare)
                continue
            prev = pieces[-1]
            # Attach punctuation / apostrophe fragments without a new space.
            if bare[0] in ",.!?;:)]}'\"%" or prev[-1] in "([{'\"$-":
                pieces.append(bare)
            elif bare.startswith("'") and len(bare) <= 3:
                pieces.append(bare)
            else:
                pieces.append(" " + bare)
        out = "".join(pieces)
    return normalize_whisper_text(re.sub(r"\s+", " ", out).strip())


def _estimate_cue_max_duration(text: str) -> float:
    n = max(_display_len(text), 1)
    if _is_cjk_heavy(text):
        return max(0.9, min(_MAX_CUE_DURATION_S, n * 0.38 + 0.55))
    return max(1.0, min(_MAX_CUE_DURATION_S, n * 0.12 + 0.8))


def _iter_segment_words(seg: Any) -> list[tuple[str, float, float]]:
    words = getattr(seg, "words", None) or []
    out: list[tuple[str, float, float]] = []
    for w in words:
        # Preserve leading space — Whisper uses it as the Latin word boundary.
        raw_token = str(getattr(w, "word", "") or "")
        if not raw_token or not raw_token.strip():
            continue
        token = raw_token
        start = float(getattr(w, "start", 0.0) or 0.0)
        end = float(getattr(w, "end", start) or start)
        if end < start:
            end = start
        # Drop clearly broken word spans (turbo alignment glitches).
        dur = end - start
        n = max(_display_len(token), 1)
        max_dur = max(0.6, min(3.5, n * 0.45 + 0.4))
        if dur > max_dur * 2.5:
            end = start + max_dur
        out.append((token, start, end))
    return out


def _cues_from_word_pairs(
    pairs: list[tuple[str, float, float]],
    *,
    include_words: bool = False,
    meta: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    if not pairs:
        return []
    cues: list[dict[str, Any]] = []
    buf: list[tuple[str, float, float]] = []
    cue_start = pairs[0][1]
    cue_end = pairs[0][2]
    sample = _join_whisper_words([p[0] for p in pairs[:12]])
    cjk_heavy = _is_cjk_heavy(sample)
    max_chars = _MAX_CJK_CHARS if cjk_heavy else _MAX_LATIN_CHARS
    soft = max(10, int(max_chars * 0.55))
    gap_break = _WORD_GAP_BREAK_S if cjk_heavy else _WORD_GAP_BREAK_S_LATIN
    extra = dict(meta or {})

    def _flush() -> None:
        nonlocal buf, cue_start, cue_end
        tokens = [p[0] for p in buf]
        text = _join_whisper_words(tokens)
        if text:
            end_t = max(cue_end, cue_start + 0.35)
            end_t = min(end_t, cue_start + _estimate_cue_max_duration(text))
            cue: dict[str, Any] = {
                "start": cue_start,
                "end": max(end_t, cue_start + 0.35),
                "text": text,
            }
            cue.update(extra)
            if include_words:
                cue["words"] = [
                    {
                        "word": str(tok).strip() or tok,
                        "start": float(st),
                        "end": float(en),
                    }
                    for tok, st, en in buf
                ]
            cues.append(cue)
        buf = []

    for token, start_f, end_f in pairs:
        if buf and start_f - cue_end >= gap_break:
            _flush()
        if not buf:
            cue_start = start_f
        buf.append((token, start_f, end_f))
        cue_end = max(end_f, cue_start)
        joined = _join_whisper_words([p[0] for p in buf])
        last_ch = token.strip()[-1] if token.strip() else ""
        disp = _display_len(joined)
        should_break = False
        if last_ch in _SENTENCE_END and disp >= 1:
            should_break = True
        elif disp >= soft and last_ch in _CLAUSE_BREAK:
            should_break = True
        elif disp >= max_chars:
            should_break = True
        elif (cue_end - cue_start) >= _MAX_CUE_DURATION_S and disp >= 6:
            should_break = True
        if should_break:
            _flush()

    if buf:
        _flush()
    return cues


def _cues_from_whisper_segments(
    segments: Iterable[Any],
    *,
    include_words: bool = False,
) -> list[dict[str, Any]]:
    """Prefer word-level timestamps; optionally attach per-word timings."""
    cues: list[dict[str, Any]] = []
    for seg in segments:
        text = normalize_whisper_text(str(getattr(seg, "text", "") or "").strip())
        meta: dict[str, Any] = {}
        try:
            if getattr(seg, "avg_logprob", None) is not None:
                meta["avgLogprob"] = float(seg.avg_logprob)
        except Exception:
            pass
        try:
            if getattr(seg, "no_speech_prob", None) is not None:
                meta["noSpeechProb"] = float(seg.no_speech_prob)
        except Exception:
            pass
        pairs = _iter_segment_words(seg)
        if pairs:
            part = _cues_from_word_pairs(pairs, include_words=include_words, meta=meta)
            if part:
                cues.extend(part)
                continue
        if not text:
            continue
        start = float(getattr(seg, "start", 0) or 0)
        end = float(getattr(seg, "end", start) or start)
        if end <= start:
            end = start + 0.6
        if _display_len(text) > 40 and (end - start) > 8.0:
            parts = [
                p.strip()
                for p in re.split(r"(?<=[。！？!?．.｡])\s*", text)
                if p and p.strip()
            ]
            if len(parts) > 1:
                total = sum(max(_display_len(p), 1) for p in parts) or 1
                t = start
                span = end - start
                for i, part_text in enumerate(parts):
                    dur = span * (_display_len(part_text) / total)
                    end_t = end if i == len(parts) - 1 else min(end, t + max(dur, 0.4))
                    cue = {
                        "start": t,
                        "end": max(end_t, t + 0.35),
                        "text": part_text,
                    }
                    cue.update(meta)
                    cues.append(cue)
                    t = end_t
                continue
        end = min(end, start + _estimate_cue_max_duration(text))
        cue = {"start": start, "end": max(end, start + 0.35), "text": text}
        cue.update(meta)
        cues.append(cue)
    return cues


def _normalize_clip_dicts(
    clip_timestamps: list[dict[str, float]] | list[float] | None,
) -> list[dict[str, float]]:
    if not clip_timestamps:
        return []
    if isinstance(clip_timestamps[0], dict):
        out: list[dict[str, float]] = []
        for c in clip_timestamps:  # type: ignore[assignment]
            try:
                s = float(c["start"])  # type: ignore[index]
                e = float(c["end"])  # type: ignore[index]
            except Exception:
                continue
            if e > s:
                out.append({"start": s, "end": e})
        return sorted(out, key=lambda x: (x["start"], x["end"]))
    flat = [float(x) for x in clip_timestamps]  # type: ignore[arg-type]
    out = []
    for i in range(0, len(flat) - 1, 2):
        s, e = flat[i], flat[i + 1]
        if e > s:
            out.append({"start": s, "end": e})
    return out


def pack_clips_into_windows(
    clips: list[dict[str, float]] | None,
    *,
    max_span_s: float = _WINDOWED_MAX_SPAN_S,
    merge_gap_s: float = _WINDOWED_CLIP_MERGE_GAP_S,
) -> list[dict[str, float]]:
    """Pack speech clips into ≤max_span_s windows for crash-safe ASR."""
    if not clips:
        return []
    ordered = sorted(
        (
            {
                "start": float(c.get("start") or 0),
                "end": float(c.get("end") or 0),
            }
            for c in clips
            if float(c.get("end") or 0) > float(c.get("start") or 0)
        ),
        key=lambda c: (c["start"], c["end"]),
    )
    if not ordered:
        return []
    # Soft-merge nearby islands first (keep clusters tight).
    merged: list[dict[str, float]] = [dict(ordered[0])]
    soft_span = min(36.0, float(max_span_s))
    for clip in ordered[1:]:
        prev = merged[-1]
        gap = float(clip["start"]) - float(prev["end"])
        span = float(clip["end"]) - float(prev["start"])
        if gap <= merge_gap_s and span <= soft_span:
            prev["end"] = max(float(prev["end"]), float(clip["end"]))
        else:
            merged.append(dict(clip))
    # Pack merged islands into windows under max_span_s.
    windows: list[dict[str, float]] = []
    cur: dict[str, float] | None = None
    pack_gap = max(merge_gap_s * 4.0, 2.0)
    for clip in merged:
        if cur is None:
            cur = dict(clip)
            continue
        gap = float(clip["start"]) - float(cur["end"])
        span = float(clip["end"]) - float(cur["start"])
        if gap <= pack_gap and span <= float(max_span_s):
            cur["end"] = max(float(cur["end"]), float(clip["end"]))
        else:
            windows.append(cur)
            cur = dict(clip)
    if cur is not None:
        windows.append(cur)
    return windows


def fixed_time_windows(
    duration_s: float,
    *,
    window_s: float = _WINDOWED_MAX_SPAN_S,
    overlap_s: float = _WINDOWED_FIXED_OVERLAP_S,
) -> list[dict[str, float]]:
    """Fixed timeline windows when no external VAD clips are available."""
    dur = max(0.0, float(duration_s or 0))
    win = max(30.0, float(window_s or _WINDOWED_MAX_SPAN_S))
    ov = max(0.0, min(float(overlap_s or 0), win * 0.25))
    if dur <= 0:
        return []
    if dur <= win + 1.0:
        return [{"start": 0.0, "end": dur}]
    out: list[dict[str, float]] = []
    step = max(15.0, win - ov)
    t = 0.0
    while t < dur - 0.05:
        end = min(dur, t + win)
        out.append({"start": t, "end": end})
        if end >= dur - 0.05:
            break
        t += step
    return out


# WhisperSeg often misses quiet dialogue islands on soft-AV; fill large gaps so
# anime-whisper still decodes those regions (crash-safe ≤180s windows).
_WINDOWED_GAP_FILL_S = 36.0


def fill_timeline_gaps(
    windows: list[dict[str, float]] | None,
    duration_s: float,
    *,
    max_gap_s: float = _WINDOWED_GAP_FILL_S,
    fill_window_s: float = _WINDOWED_MAX_SPAN_S,
) -> list[dict[str, float]]:
    """Insert fixed windows into large gaps between VAD-packed windows."""
    dur = max(0.0, float(duration_s or 0))
    gap_lim = max(8.0, float(max_gap_s or _WINDOWED_GAP_FILL_S))
    fill_win = max(30.0, float(fill_window_s or _WINDOWED_MAX_SPAN_S))
    ordered = sorted(
        (
            {
                "start": float(w.get("start") or 0),
                "end": float(w.get("end") or 0),
            }
            for w in (windows or [])
            if float(w.get("end") or 0) > float(w.get("start") or 0)
        ),
        key=lambda w: (w["start"], w["end"]),
    )
    if dur <= 0:
        return ordered
    if not ordered:
        return fixed_time_windows(dur, window_s=fill_win)

    out: list[dict[str, float]] = []
    cursor = 0.0

    def _append_gap(gap_start: float, gap_end: float) -> None:
        span = float(gap_end) - float(gap_start)
        if span < gap_lim:
            return
        fills = fixed_time_windows(span, window_s=fill_win)
        for g in fills:
            out.append(
                {
                    "start": gap_start + float(g["start"]),
                    "end": min(gap_end, gap_start + float(g["end"])),
                }
            )

    for win in ordered:
        ws, we = float(win["start"]), float(win["end"])
        _append_gap(cursor, ws)
        out.append({"start": ws, "end": we})
        cursor = max(cursor, we)
    _append_gap(cursor, dur)

    # Merge tiny overlaps / touching windows, but stay crash-safe (≤fill_win)
    if not out:
        return fixed_time_windows(dur, window_s=fill_win)
    merged: list[dict[str, float]] = [dict(out[0])]
    for win in out[1:]:
        prev = merged[-1]
        gap = float(win["start"]) - float(prev["end"])
        span = float(win["end"]) - float(prev["start"])
        if gap <= 0.05 and span <= fill_win + 0.5:
            prev["end"] = max(float(prev["end"]), float(win["end"]))
        else:
            merged.append(dict(win))
    return merged


def _shift_cues(cues: list[dict[str, Any]], offset_s: float) -> list[dict[str, Any]]:
    if not cues or abs(float(offset_s or 0)) < 1e-9:
        return list(cues or [])
    off = float(offset_s)
    out: list[dict[str, Any]] = []
    for cue in cues:
        if not isinstance(cue, dict):
            continue
        item = {
            **cue,
            "start": float(cue.get("start") or 0) + off,
            "end": float(cue.get("end") or 0) + off,
        }
        words = cue.get("words")
        if isinstance(words, list):
            item["words"] = [
                {
                    **w,
                    "start": float(w.get("start") or 0) + off,
                    "end": float(w.get("end") or 0) + off,
                }
                if isinstance(w, dict)
                else w
                for w in words
            ]
        out.append(item)
    return out


# anime-whisper emits one segment per ~30s decode step with end≈start (CPS 100+).
# ja_av CPS hallucination filter then drops all real dialogue. Repair before cleanup.
# Expand by speaking-rate estimate — do NOT fill silence until the next cue
# (that produced wall-to-wall subtitles covering ~80% of the timeline).
_COLLAPSE_CPS = 40.0
_COLLAPSE_MIN_CHARS = 8
_DEFAULT_CHUNK_SPAN_S = 30.0
_REPAIR_TARGET_CPS_JA = 9.0
_REPAIR_TARGET_CPS_LATIN = 14.0
# Keep under quality._MAX_CPS_JA (28) with margin after repair.
_REPAIR_MIN_CPS = 20.0
_REPAIR_MAX_EXPAND_S = 24.0
_REPAIR_PART_GAP_S = 0.08
_REPAIR_RUN_GAP_S = 0.12


def _cue_is_timestamp_collapsed(cue: dict[str, Any]) -> bool:
    text = str(cue.get("text") or "").strip()
    if not text:
        return False
    n = _display_len(text)
    if n < _COLLAPSE_MIN_CHARS:
        return False
    start = float(cue.get("start") or 0)
    end = float(cue.get("end") or start)
    dur = max(0.0, end - start)
    if dur <= 0.08:
        return True
    return (n / dur) > _COLLAPSE_CPS


def _estimate_speech_duration_s(text: str, *, available_s: float) -> float:
    """Reading-rate duration for collapsed anime-whisper blobs."""
    n = max(_display_len(text), 1)
    target = _REPAIR_TARGET_CPS_JA if _is_cjk_heavy(text) else _REPAIR_TARGET_CPS_LATIN
    needed = n / target
    min_dur = n / _REPAIR_MIN_CPS
    dur = max(min_dur, needed, 0.45)
    cap = min(max(float(available_s), 0.45), _REPAIR_MAX_EXPAND_S)
    return min(dur, cap)


def _split_cue_text_parts(text: str, *, max_chars: int) -> list[str]:
    raw = str(text or "").strip()
    if not raw:
        return []
    parts = [
        p.strip()
        for p in re.split(r"(?<=[。！？!?．.｡…])\s*", raw)
        if p and p.strip()
    ]
    if not parts:
        parts = [raw]
    # Further split long clauses without sentence enders.
    out: list[str] = []
    limit = max(8, int(max_chars))
    for part in parts:
        if _display_len(part) <= limit:
            out.append(part)
            continue
        buf = ""
        for ch in part:
            buf += ch
            if _display_len(buf) >= max(6, int(limit * 0.55)) and ch in _CLAUSE_BREAK:
                out.append(buf.strip())
                buf = ""
            elif _display_len(buf) >= limit:
                out.append(buf.strip())
                buf = ""
        if buf.strip():
            out.append(buf.strip())
    return [p for p in out if p]


def _split_expanded_cue(
    cue: dict[str, Any],
    *,
    max_chars: int = _MAX_CJK_CHARS,
    part_gap_s: float = _REPAIR_PART_GAP_S,
) -> list[dict[str, Any]]:
    """
    Split a cue across its (already rate-estimated) span.

    Each part gets proportional time; the last part does NOT absorb leftover
    silence up to ``end`` (that caused 10–20s trailing cues).
    """
    text = str(cue.get("text") or "").strip()
    if not text:
        return []
    start = float(cue.get("start") or 0)
    end = float(cue.get("end") or start)
    if end <= start:
        end = start + 0.6
    parts = _split_cue_text_parts(text, max_chars=max_chars)
    meta = {
        k: v
        for k, v in cue.items()
        if k not in ("start", "end", "text", "words")
    }
    if len(parts) <= 1:
        item = {**meta, "start": start, "end": max(end, start + 0.35), "text": text}
        return [item]
    weights = [max(_display_len(p), 1) for p in parts]
    total_w = float(sum(weights)) or 1.0
    gap = max(0.0, float(part_gap_s))
    span = end - start
    usable = max(0.35 * len(parts), span - gap * (len(parts) - 1))
    t = start
    out: list[dict[str, Any]] = []
    for i, part_text in enumerate(parts):
        dur = usable * (weights[i] / total_w)
        # Cap individual parts so one clause cannot monopolize a chunk.
        dur = min(max(dur, 0.35), _MAX_CUE_DURATION_S)
        end_t = t + dur
        if i == len(parts) - 1:
            # Stay within parent end, but never stretch into silence.
            end_t = min(end_t, end)
        out.append({**meta, "start": t, "end": max(end_t, t + 0.35), "text": part_text})
        t = end_t + (gap if i < len(parts) - 1 else 0.0)
        if t >= end and i < len(parts) - 1:
            # Remaining parts: pack tightly at the end edge.
            t = min(t, end - 0.35 * (len(parts) - i - 1))
    return out


def repair_collapsed_asr_cues(
    cues: list[dict[str, Any]] | None,
    *,
    media_end_s: float | None = None,
    max_part_chars: int = _MAX_CJK_CHARS,
) -> list[dict[str, Any]]:
    """
    Stretch anime-whisper collapsed timestamps by speaking rate, then split.

    Without this, each ~30s of speech becomes a 0.3–0.9s cue; soft-AV CPS
    filtering treats that as hallucination and deletes the dialogue.

    Expansion uses char/CPS estimates and stops early — filling until the next
    cue start produced wall-to-wall subtitles with no silence gaps.
    """
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    if not ordered:
        return []
    n = len(ordered)
    for i, cue in enumerate(ordered):
        if not _cue_is_timestamp_collapsed(cue):
            continue
        start = float(cue.get("start") or 0)
        if i + 1 < n:
            boundary = float(ordered[i + 1].get("start") or start)
        elif media_end_s is not None and float(media_end_s) > start:
            boundary = float(media_end_s)
        else:
            boundary = start + _DEFAULT_CHUNK_SPAN_S
        available = max(0.45, boundary - start - (0.05 if i + 1 < n else 0.0))
        text = str(cue.get("text") or "")
        cue["end"] = start + _estimate_speech_duration_s(text, available_s=available)
    out: list[dict[str, Any]] = []
    for cue in ordered:
        text = str(cue.get("text") or "")
        dur = float(cue.get("end") or 0) - float(cue.get("start") or 0)
        if _display_len(text) > max_part_chars or dur > _MAX_CUE_DURATION_S:
            out.extend(_split_expanded_cue(cue, max_chars=max_part_chars))
        else:
            out.append(cue)
    return out


def retime_wall_to_wall_cues(
    cues: list[dict[str, Any]] | None,
    *,
    target_cps: float | None = None,
    min_cps: float = _REPAIR_MIN_CPS,
    part_gap_s: float = _REPAIR_PART_GAP_S,
    run_gap_s: float = _REPAIR_RUN_GAP_S,
) -> list[dict[str, Any]]:
    """
    Shrink over-long cues in place to speaking-rate durations.

    Used to fix SRTs from an earlier repair that filled silence between
    anime-whisper 30s decode steps. Each cue keeps its start (rough timeline
    anchor); only ``end`` is pulled in so later cues stay sync'd to audio.
    Packing a whole touching-run to the run start would desync mid/late lines.
    """
    del run_gap_s  # kept for call-site compat; in-place shrink needs no runs
    if not cues:
        return []
    ordered = sorted(
        (dict(c) for c in cues if isinstance(c, dict) and str(c.get("text") or "").strip()),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    )
    if not ordered:
        return []
    gap = max(0.0, float(part_gap_s))
    out: list[dict[str, Any]] = []
    for i, cue in enumerate(ordered):
        item = dict(cue)
        text = str(item.get("text") or "")
        start = float(item.get("start") or 0)
        end = float(item.get("end") or start)
        n = max(_display_len(text), 1)
        tgt = float(
            target_cps
            if target_cps is not None
            else (
                _REPAIR_TARGET_CPS_JA
                if _is_cjk_heavy(text)
                else _REPAIR_TARGET_CPS_LATIN
            )
        )
        need = max(n / max(float(min_cps), 1.0), n / tgt, 0.45)
        need = min(need, _MAX_CUE_DURATION_S)
        new_end = start + need
        # Never spill into the next cue's start (near-duplicate starts → tiny slot).
        if i + 1 < len(ordered):
            next_start = float(ordered[i + 1].get("start") or start)
            if next_start > start + 1e-3:
                slot = next_start - start
                cap = next_start - min(gap, max(0.0, slot * 0.25))
                new_end = min(new_end, cap)
                if new_end <= start:
                    new_end = start + min(0.2, slot * 0.5)
        # Only shrink (do not extend short accurate cues).
        if end > start + 0.05:
            item["end"] = min(end, max(new_end, start + 0.05))
        else:
            item["end"] = max(new_end, start + 0.35)
        if item["end"] <= start:
            item["end"] = start + 0.05
        out.append(item)
    # Final pass: hard-clamp any residual overlaps from near-duplicate starts.
    for i in range(len(out) - 1):
        start_i = float(out[i]["start"])
        next_start = float(out[i + 1]["start"])
        if next_start <= start_i + 1e-3:
            out[i]["end"] = min(float(out[i]["end"]), start_i + 0.05)
            continue
        limit = next_start - gap
        if float(out[i]["end"]) > limit:
            out[i]["end"] = max(start_i + 0.05, limit)
    return out


_TIMING_SPAM_EXACT = frozenset(
    {
        "はい",
        "うん",
        "ええ",
        "あっ",
        "ん",
        "あー",
        "はぁ",
        "ええっ",
        "あっ…",
        "ん…",
    }
)


def _timing_cue_usable(cue: dict[str, Any]) -> bool:
    """Drop timing-model filler islands that pollute the speech timeline."""
    text = str(cue.get("text") or "").strip()
    if not text:
        return False
    start = float(cue.get("start") or 0)
    end = float(cue.get("end") or start)
    dur = max(0.0, end - start)
    if dur < 0.12:
        return False
    bare = re.sub(r"[\s。．.!！?？、,…・･]+", "", text)
    if not bare:
        return False
    if bare in _TIMING_SPAM_EXACT and dur < 0.75:
        return False
    if len(bare) <= 1 and dur < 1.0:
        return False
    return True


def _speech_intervals_from_timing_cues(
    cues: list[dict[str, Any]] | None,
    *,
    merge_gap_s: float = 0.4,
) -> list[tuple[float, float]]:
    intervals: list[tuple[float, float]] = []
    for cue in sorted(
        (c for c in (cues or []) if isinstance(c, dict) and _timing_cue_usable(c)),
        key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)),
    ):
        s = float(cue.get("start") or 0)
        e = float(cue.get("end") or s)
        if e <= s:
            continue
        if intervals and s <= intervals[-1][1] + merge_gap_s:
            intervals[-1] = (intervals[-1][0], max(intervals[-1][1], e))
        else:
            intervals.append((s, e))
    return intervals


def _media_time_at_speech_pos(
    pos_s: float,
    intervals: list[tuple[float, float]],
) -> float:
    if not intervals:
        return max(0.0, float(pos_s))
    remain = max(0.0, float(pos_s))
    total = sum(max(0.0, e - s) for s, e in intervals)
    if total <= 0:
        return intervals[0][0]
    if remain >= total:
        return intervals[-1][1]
    for s, e in intervals:
        dur = max(0.0, e - s)
        if remain <= dur:
            return s + remain
        remain -= dur
    return intervals[-1][1]


def _island_at_speech_pos(
    pos_s: float,
    intervals: list[tuple[float, float]],
) -> tuple[float, float]:
    """Return (media_pos, island_media_end) for a speech-timeline cursor."""
    if not intervals:
        p = max(0.0, float(pos_s))
        return p, p
    remain = max(0.0, float(pos_s))
    total = sum(max(0.0, e - s) for s, e in intervals)
    if remain >= total:
        return intervals[-1][1], intervals[-1][1]
    for s, e in intervals:
        dur = max(0.0, e - s)
        if remain <= dur:
            return s + remain, e
        remain -= dur
    return intervals[-1][1], intervals[-1][1]


def _norm_match_text(text: str) -> str:
    s = unicodedata.normalize("NFKC", str(text or ""))
    return _MATCH_PUNCT.sub("", s).lower()


def _char_bigrams(s: str) -> set[str]:
    if not s:
        return set()
    if len(s) < 2:
        return {s}
    return {s[i : i + 2] for i in range(len(s) - 1)}


def _cue_text_similarity(a: str, b: str) -> float:
    """Similarity for matching anime wording onto timing-model cues."""
    na, nb = _norm_match_text(a), _norm_match_text(b)
    if not na or not nb:
        return 0.0
    if na == nb:
        return 1.0
    if na in nb or nb in na:
        ratio = min(len(na), len(nb)) / max(len(na), len(nb))
        return 0.72 + 0.28 * ratio
    A, B = _char_bigrams(na), _char_bigrams(nb)
    jacc = (len(A & B) / len(A | B)) if A and B else 0.0
    seq = SequenceMatcher(None, na, nb).ratio()
    return max(jacc, seq)


def _timing_has_matchable_text(timing_cues: list[dict[str, Any]]) -> bool:
    for cue in timing_cues:
        bare = _norm_match_text(str(cue.get("text") or ""))
        if bare and bare not in ("speech", "spk", "vad"):
            return True
    return False


def _align_by_fuzzy_match(
    text_cues: list[dict[str, Any]],
    timing_cues: list[dict[str, Any]],
    *,
    min_sim: float = _FUZZY_MIN_SIM,
    part_gap_s: float = 0.06,
) -> list[dict[str, Any]] | None:
    """
    Copy start/end from timing-model cues onto anime texts when wording matches.

    Monotonic greedy match with lookahead; unmatched cues are placed in the
    silence/speech gap between neighboring matches (rate-based duration).
    Returns None when too few matches to trust (caller falls back).
    """
    texts = [
        dict(c)
        for c in text_cues
        if isinstance(c, dict) and str(c.get("text") or "").strip()
    ]
    timings = [
        dict(c)
        for c in timing_cues
        if isinstance(c, dict) and _timing_cue_usable(c)
    ]
    if not texts or not timings or not _timing_has_matchable_text(timings):
        return None

    matches: dict[int, int] = {}
    last_j = -1
    for i, tc in enumerate(texts):
        lo = last_j + 1
        hi = min(len(timings), lo + _FUZZY_LOOKAHEAD)
        best_j, best_s = -1, float(min_sim)
        for j in range(lo, hi):
            s = _cue_text_similarity(
                str(tc.get("text") or ""),
                str(timings[j].get("text") or ""),
            )
            if s > best_s + 1e-9:
                best_s, best_j = s, j
        if best_j >= 0:
            matches[i] = best_j
            last_j = best_j

    if len(matches) < max(1, int(round(len(texts) * 0.28))):
        return None

    gap = max(0.0, float(part_gap_s))
    media_end = max(float(t.get("end") or 0) for t in timings)
    out: list[dict[str, Any] | None] = [None] * len(texts)
    for i, j in matches.items():
        tj = timings[j]
        item = dict(texts[i])
        item["start"] = float(tj.get("start") or 0)
        item["end"] = max(
            float(tj.get("end") or item["start"]),
            float(item["start"]) + 0.2,
        )
        item.pop("words", None)
        out[i] = item

    # Fill unmatched between matched neighbors.
    for i in range(len(texts)):
        if out[i] is not None:
            continue
        prev_e = 0.0
        for k in range(i - 1, -1, -1):
            if out[k] is not None:
                prev_e = float(out[k]["end"])
                break
        next_s = media_end if media_end > 0 else prev_e + 2.0
        for k in range(i + 1, len(texts)):
            if out[k] is not None:
                next_s = float(out[k]["start"])
                break
        text = str(texts[i].get("text") or "")
        n = max(_display_len(text), 1)
        dur = max(0.35, min(_MAX_CUE_DURATION_S, n / 12.0))
        room = max(0.35, next_s - prev_e - gap)
        dur = min(dur, room)
        start = prev_e + min(gap, max(0.0, (room - dur) * 0.35))
        if start + dur > next_s - gap * 0.5:
            start = max(prev_e, next_s - dur - gap)
        end = min(start + dur, next_s)
        if end <= start:
            end = start + 0.35
        item = dict(texts[i])
        item["start"] = start
        item["end"] = end
        item.pop("words", None)
        out[i] = item

    final = [c for c in out if c is not None]
    # Enforce non-overlap / order.
    for i in range(1, len(final)):
        prev = final[i - 1]
        cur = final[i]
        if float(cur["start"]) < float(prev["end"]):
            cur["start"] = float(prev["end"]) + gap
        if float(cur["end"]) <= float(cur["start"]):
            cur["end"] = float(cur["start"]) + 0.35
    return final


def _align_proportional_to_intervals(
    texts_in: list[dict[str, Any]],
    intervals: list[tuple[float, float]],
    *,
    part_gap_s: float = 0.06,
) -> list[dict[str, Any]]:
    total_speech = sum(max(0.0, e - s) for s, e in intervals)
    if total_speech < 0.2:
        return texts_in

    weights = [max(_display_len(str(c.get("text") or "")), 1) for c in texts_in]
    total_w = float(sum(weights)) or 1.0
    gap = max(0.0, float(part_gap_s))
    usable = max(0.25 * len(texts_in), total_speech - gap * max(0, len(texts_in) - 1))

    out: list[dict[str, Any]] = []
    cursor = 0.0
    for i, cue in enumerate(texts_in):
        alloc = usable * (weights[i] / total_w)
        alloc = max(0.2, min(alloc, _MAX_CUE_DURATION_S))
        remain = max(0.0, total_speech - cursor)
        if remain <= 0.05:
            s = max(intervals[-1][0], intervals[-1][1] - 0.35)
            e = intervals[-1][1]
            item = dict(cue)
            item["start"] = s
            item["end"] = max(e, s + 0.2)
            item.pop("words", None)
            out.append(item)
            continue
        alloc = min(alloc, remain)
        m0, island_e = _island_at_speech_pos(cursor, intervals)
        m1_raw = _media_time_at_speech_pos(cursor + alloc, intervals)
        m1 = min(m1_raw, island_e)
        if m1 <= m0:
            m1 = min(island_e, m0 + 0.2)
        item = dict(cue)
        item["start"] = m0
        item["end"] = m1
        item.pop("words", None)
        out.append(item)
        cursor += alloc
        if i < len(texts_in) - 1:
            cursor = min(total_speech, cursor + gap)
    for i, item in enumerate(out):
        text = str(item.get("text") or "")
        n = max(_display_len(text), 1)
        min_dur = max(0.35, min(_MAX_CUE_DURATION_S, n / 20.0))
        start = float(item.get("start") or 0)
        end = float(item.get("end") or start)
        if end - start >= min_dur - 1e-6:
            continue
        limit = start + _MAX_CUE_DURATION_S
        if i + 1 < len(out):
            limit = min(limit, float(out[i + 1].get("start") or limit) - gap)
        item["end"] = max(end, min(start + min_dur, limit))
        if item["end"] <= start:
            item["end"] = start + 0.35
    return out


def align_text_cues_to_timing(
    text_cues: list[dict[str, Any]] | None,
    timing_cues: list[dict[str, Any]] | None,
    *,
    part_gap_s: float = 0.06,
) -> list[dict[str, Any]]:
    """
    Keep anime-whisper (or other) cue texts in order; place them on a speech
    timeline derived from a timing-capable Whisper model.

    Prefer sentence-level fuzzy match (copy timing cue start/end when wording
    is similar). Fall back to proportional speech-island mapping when the
    timing pass has no matchable text (e.g. TEN VAD-only) or match rate is low.
    """
    texts_in = [
        dict(c)
        for c in (text_cues or [])
        if isinstance(c, dict) and str(c.get("text") or "").strip()
    ]
    if not texts_in:
        return []

    fuzzy = _align_by_fuzzy_match(
        texts_in,
        list(timing_cues or []),
        part_gap_s=part_gap_s,
    )
    if fuzzy is not None:
        return fuzzy

    intervals = _speech_intervals_from_timing_cues(timing_cues)
    if not intervals:
        return texts_in
    return _align_proportional_to_intervals(
        texts_in,
        intervals,
        part_gap_s=part_gap_s,
    )


def resolve_and_align_window_cues(
    text_cues: list[dict[str, Any]] | None,
    *,
    media_path: str,
    language: str,
    device: str,
    beam_size: int,
    vad_options: dict[str, Any] | None,
    timing_model: str,
    should_cancel: Callable[[], bool] | None = None,
    media_end_s: float | None = None,
) -> list[dict[str, Any]]:
    """
    Align ``text_cues`` onto real timestamps.

    Preference for auto / empty:
    1. Second ASR pass (``whisper-ja-1.5b`` / turbo) + fuzzy sentence match
    Explicit ``ten`` / ``vad`` → TEN VAD-only proportional islands.
    Explicit ``whisperx`` / ``wav2vec2`` → CTC forced align (+ ASR fallback).
    Explicit ASR model ids skip VAD and go straight to that model.
    """
    texts = list(text_cues or [])
    mid = str(timing_model or "").strip()
    mid_l = mid.lower()
    if not texts:
        return texts

    # auto/empty → dual ASR (fuzzy). TEN only when explicitly requested.
    prefer_vad = mid_l in ("ten", "ten-vad", "ten_vad", "vad")
    prefer_w2v = mid_l in ("whisperx", "wav2vec2", "wav2vec", "w2v")
    force_asr_only = bool(mid) and not prefer_vad and not prefer_w2v and mid_l not in (
        "",
        "auto",
    )

    if prefer_w2v:
        try:
            from .wav2vec_align import align_cues_wav2vec2, wav2vec_align_available

            if wav2vec_align_available():
                if should_cancel and should_cancel():
                    raise RuntimeError("cancelled")
                aligned = align_cues_wav2vec2(
                    texts,
                    media_path=media_path,
                    device=device,
                    media_end_s=media_end_s,
                )
                if aligned:
                    return aligned
        except Exception as err:
            _log.warning("wav2vec2 / WhisperX-style align unavailable: %s", err)

    if prefer_vad or prefer_w2v:
        try:
            from ..vad.ten_vad_seg import align_cues_ten_vad, ten_vad_available

            if ten_vad_available():
                if should_cancel and should_cancel():
                    raise RuntimeError("cancelled")
                aligned = align_cues_ten_vad(
                    texts,
                    media_path=media_path,
                    media_end_s=media_end_s,
                )
                if aligned:
                    return aligned
        except Exception as err:
            _log.warning("TEN VAD timing unavailable: %s", err)

    if force_asr_only:
        asr_mid = mid
    else:
        from ..models_catalog import resolve_timing_align_model

        asr_mid = resolve_timing_align_model("anime-whisper", preferred=None) or ""
    if not asr_mid or asr_mid.lower() in (
        "whisperx",
        "wav2vec2",
        "wav2vec",
        "w2v",
        "auto",
        "ten",
        "ten-vad",
        "ten_vad",
        "vad",
    ):
        return texts

    safe_vad = dict(vad_options or {})
    safe_vad["hallucinationSilenceThreshold"] = 0
    try:
        timing = whisper_transcribe(
            media_path=media_path,
            language=language,
            asr_model=asr_mid,
            device=device,
            beam_size=max(1, min(5, int(beam_size or 5))),
            vad_options=safe_vad,
            clip_timestamps=None,
            force_no_vad=True,
            initial_prompt=None,
            hotwords=None,
            on_progress=None,
            on_cue=None,
            should_cancel=should_cancel,
            include_words=False,
            word_timestamps=True,
            _allow_windowed=False,
            timing_align_model="",  # never recurse
        )
    except Exception as err:
        _log.warning("timing align model %s failed: %s", asr_mid, err)
        return texts
    return align_text_cues_to_timing(texts, timing)


def _anime_ten_beam_size(beam_size: int | None) -> int:
    """Anime TEN islands always use greedy decode (WhisperJAV / litagin)."""
    _ = beam_size  # request beam ignored — short islands do not benefit
    return 1


def _resolve_island_vad_backend(timing_align_model: str | None) -> str | None:
    """Pick short-frame island VAD: ``ten`` | ``firered`` | ``None`` (skip).

    ``None`` / ``auto`` / ``vad`` → TEN (default).
    ``firered`` / ``firered-vad`` → FireRedVAD.
    Explicit ``""`` / ``off`` / ``rate`` → no island ASR (windowed/CPS).
    Other ids (whisper-ja, wav2vec2, …) → dual-align path, not island ASR.
    """
    if timing_align_model is None:
        return "ten"
    raw = str(timing_align_model).strip().lower().replace("_", "-")
    if raw in ("auto", "vad"):
        return "ten"
    if raw in ("ten", "ten-vad"):
        return "ten"
    if raw in ("firered", "firered-vad", "fire-red", "fireredvad"):
        return "firered"
    if not raw or raw in ("off", "false", "0", "no", "none", "rate", "cps"):
        return None
    return None


def _anime_uses_ten_island_asr(timing_align_model: str | None) -> bool:
    """True when anime path should run VAD-owned short-frame island ASR."""
    return _resolve_island_vad_backend(timing_align_model) is not None


def _split_island_spans(
    start: float,
    end: float,
    *,
    max_span_s: float = _WINDOWED_MAX_SPAN_S,
) -> list[tuple[float, float]]:
    """Split oversized VAD islands (CT2-safe ≤180s, or anime short frames ≤5s)."""
    s = float(start)
    e = float(end)
    if e <= s:
        return []
    max_s = max(1.0, float(max_span_s or _WINDOWED_MAX_SPAN_S))
    if e - s <= max_s + 1e-6:
        return [(s, e)]
    out: list[tuple[float, float]] = []
    cursor = s
    while cursor < e - 1e-6:
        nxt = min(e, cursor + max_s)
        out.append((cursor, nxt))
        cursor = nxt
    return out


def group_vad_intervals(
    intervals: list[tuple[float, float]] | None,
    *,
    chunk_threshold_s: float = _ANIME_VAD_CHUNK_THRESHOLD_S,
    max_group_duration_s: float = _ANIME_VAD_MAX_GROUP_S,
) -> list[tuple[float, float]]:
    """
    VAD grouping: merge nearby speech, cap group length.

    Then hard-split any remaining oversize span so each anime ASR call stays
    inside ``max_group_duration_s`` (default 5s).
    """
    ordered = sorted(
        (
            (float(s), float(e))
            for s, e in (intervals or [])
            if float(e) > float(s)
        ),
        key=lambda p: p[0],
    )
    if not ordered:
        return []
    gap = max(0.0, float(chunk_threshold_s))
    max_g = max(1.0, float(max_group_duration_s))
    merged: list[list[float]] = [[ordered[0][0], ordered[0][1]]]
    for s, e in ordered[1:]:
        prev_s, prev_e = merged[-1]
        silence = s - prev_e
        would_exceed = (e - prev_s) > max_g
        if silence > gap or would_exceed:
            merged.append([s, e])
        else:
            merged[-1][1] = max(prev_e, e)
    out: list[tuple[float, float]] = []
    for s, e in merged:
        out.extend(_split_island_spans(s, e, max_span_s=max_g))
    return out


def _split_frame_text_chunks(text: str, *, max_chars: int = _ANIME_FRAME_CHAR_CHUNK) -> list[str]:
    """Split hierarchy: sentences → commas → ~10-char chunks."""
    raw = str(text or "").strip()
    if not raw:
        return []
    chunks = [p for p in re.split(r"(?<=[。？?！!])", raw) if p and p.strip()]
    if not chunks:
        chunks = [raw]
    if len(chunks) == 1 and len(raw) > 15:
        comma = [p for p in re.split(r"(?<=[、，,])", raw) if p and p.strip()]
        if len(comma) > 1:
            chunks = comma
    if len(chunks) == 1 and len(raw) > 20:
        limit = max(4, int(max_chars))
        n_chunks = max(2, -(-len(raw) // limit))
        size = -(-len(raw) // n_chunks)
        chunks = [raw[i : i + size] for i in range(0, len(raw), size)]
    return [c.strip() for c in chunks if c and c.strip()]


def split_frame_text_to_cues(
    text: str,
    start: float,
    end: float,
    *,
    max_chars: int = _ANIME_FRAME_CHAR_CHUNK,
) -> list[dict[str, Any]]:
    """
    Paint island text onto ``[start, end]`` with char-proportional sub-cues.

    Timing comes from the VAD frame; intra-frame splits are synthetic
    (char-proportional, not acoustic).
    """
    chunks = _split_frame_text_chunks(text, max_chars=max_chars)
    if not chunks:
        return []
    s = float(start)
    e = float(end)
    if e <= s:
        e = s + 0.35
    if len(chunks) == 1:
        return [{"start": s, "end": e, "text": chunks[0]}]
    total_chars = sum(len(c) for c in chunks) or 1
    duration = e - s
    out: list[dict[str, Any]] = []
    cursor = s
    for i, chunk in enumerate(chunks):
        if i == len(chunks) - 1:
            chunk_end = e
        else:
            chunk_end = cursor + duration * (len(chunk) / total_chars)
        out.append(
            {
                "start": cursor,
                "end": max(cursor + 0.05, chunk_end),
                "text": chunk,
            }
        )
        cursor = chunk_end
    return out


def _clamp_cues_to_span(
    cues: list[dict[str, Any]],
    start: float,
    end: float,
) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for cue in cues or []:
        item = dict(cue)
        cs = max(float(start), min(float(item.get("start") or start), float(end)))
        ce = max(cs + 0.05, min(float(item.get("end") or cs), float(end)))
        item["start"] = cs
        item["end"] = ce
        out.append(item)
    return out


def _whisper_anime_ten_island_transcribe(
    *,
    media_path: str,
    language: str,
    asr_model: str,
    device: str,
    beam_size: int,
    vad_options: dict[str, Any] | None,
    initial_prompt: str | None,
    hotwords: str | None,
    on_progress: ProgressCb | None,
    on_cue: CueCb | None,
    should_cancel: Callable[[], bool] | None,
    include_words: bool,
    duration_s: float,
    timing_align_model: str | None = None,
) -> list[dict[str, Any]] | None:
    """
    anime-whisper island VAD path: TEN or FireRed frames -> anime-whisper text.

    Timing source of truth is the VAD group ``[start, end]`` (default <=5s,
    0.5s silence gap). ASR only fills text; intra-frame cue splits are
    char-proportional, not model timestamps.

    Performance: reuse the float32 PCM from VAD decode and feed ndarray
    slices to the cached WhisperModel (no per-frame ffmpeg trim).
    """
    from ..device import resolve_ctranslate2_device
    from ..download import is_model_installed, model_local_path

    media_name = Path(media_path).name
    island_backend = _resolve_island_vad_backend(timing_align_model) or "ten"
    intervals: list[tuple[float, float]] | None = None
    audio_f32 = None
    TEN_SR = 16000
    slice_pcm_f32 = None  # set below

    if island_backend == "firered":
        from ..vad.firered_vad_seg import (
            collect_firered_vad_intervals_with_audio,
            firered_vad_available,
            firered_weights_dir,
        )
        from ..vad.ten_vad_seg import SAMPLE_RATE as TEN_SR, slice_pcm_f32

        if not firered_vad_available() or firered_weights_dir() is None:
            _log.info(
                "anime-whisper FireRed path skipped: fireredvad/weights missing | "
                "%s -> TEN/windowed fallback",
                media_name,
            )
            island_backend = "ten"
        else:
            _log.info(
                "anime-whisper FireRed path start: %s | model=%s | duration=%.1fs | "
                "chunk_gap=%.2fs | max_frame=%.1fs (VAD owns timeline)",
                media_name,
                asr_model,
                float(duration_s or 0),
                _ANIME_VAD_CHUNK_THRESHOLD_S,
                _ANIME_VAD_MAX_GROUP_S,
            )
            try:
                from ..runtime_extras import ensure_extras_for_models

                ensure_extras_for_models(
                    ["firered-vad"],
                    force=False,
                    on_progress=on_progress,
                )
                intervals, audio_f32 = collect_firered_vad_intervals_with_audio(
                    media_path,
                    max_media_s=duration_s if duration_s > 0 else None,
                    merge_gap_s=_ANIME_VAD_MERGE_GAP_S,
                    vad_options=vad_options,
                    device=device,
                )
            except Exception as err:
                _log.warning(
                    "FireRed VAD island collect failed for %s: %s -> TEN/windowed fallback",
                    media_name,
                    err,
                )
                island_backend = "ten"
                intervals = None
                audio_f32 = None
            if island_backend == "firered" and not intervals:
                _log.info(
                    "FireRed VAD found no speech islands on %s; falling back",
                    media_name,
                )
                return None

    if island_backend == "ten":
        from ..vad.ten_vad_seg import (
            SAMPLE_RATE as TEN_SR,
            collect_ten_vad_intervals_with_audio,
            slice_pcm_f32,
            ten_vad_available,
        )

        if not ten_vad_available():
            _log.info(
                "anime-whisper TEN path skipped: ten-vad not installed | %s -> windowed/CPS fallback",
                media_name,
            )
            return None

        _log.info(
            "anime-whisper TEN path start: %s | model=%s | duration=%.1fs | "
            "chunk_gap=%.2fs | max_frame=%.1fs (VAD owns timeline)",
            media_name,
            asr_model,
            float(duration_s or 0),
            _ANIME_VAD_CHUNK_THRESHOLD_S,
            _ANIME_VAD_MAX_GROUP_S,
        )
        try:
            intervals, audio_f32 = collect_ten_vad_intervals_with_audio(
                media_path,
                max_media_s=duration_s if duration_s > 0 else None,
                merge_gap_s=_ANIME_VAD_MERGE_GAP_S,
            )
        except Exception as err:
            _log.warning(
                "TEN VAD island collect failed for %s: %s -> windowed/CPS fallback",
                media_name,
                err,
            )
            return None
        if not intervals:
            _log.info(
                "TEN VAD found no speech islands on %s; falling back to windowed ASR",
                media_name,
            )
            return None

    if not intervals:
        return None

    pieces = group_vad_intervals(
        intervals,
        chunk_threshold_s=_ANIME_VAD_CHUNK_THRESHOLD_S,
        max_group_duration_s=_ANIME_VAD_MAX_GROUP_S,
    )
    if not pieces:
        _log.info(
            "TEN VAD grouping produced 0 frames on %s; falling back to windowed ASR",
            media_name,
        )
        return None

    spoken = sum(max(0.0, e - s) for s, e in pieces)
    max_span = max((e - s) for s, e in pieces) if pieces else 0.0
    _log.info(
        "anime-whisper TEN frames: %s | islands=%d -> frames=%d | spoken=%.1fs | "
        "max_frame=%.2fs | first=%.1f-%.1fs | last=%.1f-%.1fs",
        media_name,
        len(intervals),
        len(pieces),
        spoken,
        max_span,
        pieces[0][0],
        pieces[0][1],
        pieces[-1][0],
        pieces[-1][1],
    )

    if not is_model_installed(asr_model):
        _log.warning("anime-whisper TEN path: model not installed: %s", asr_model)
        return None

    try:
        from .whisper_av_shim import import_whisper_model_class

        WhisperModel, _used_ffmpeg_audio = import_whisper_model_class()
    except Exception as err:
        _log.warning("anime-whisper TEN path: cannot load Whisper class: %s", err)
        return None

    try:
        from ..runtime_gpu import inject_nvidia_lib_path

        inject_nvidia_lib_path()
    except Exception:
        pass

    requested = str(device or "auto").strip().lower()
    dev = resolve_ctranslate2_device(requested)
    compute = "float16" if dev == "cuda" else "int8"
    # ChronosJAV / litagin anime-whisper: greedy only. Short VAD islands gain
    # little from beam search and pay 15–40% wall time.
    requested_beam = max(1, min(20, int(beam_size or 1)))
    beam = _anime_ten_beam_size(beam_size)
    model_dir = str(model_local_path(asr_model))
    model = _get_cached_whisper_model(
        WhisperModel,
        model_dir,
        device=dev,
        compute_type=compute,
    )
    lang = None if not language or language == "auto" else language
    use_word_ts = bool(include_words)

    transcribe_kw: dict[str, Any] = {
        "language": lang,
        "beam_size": beam,
        "word_timestamps": use_word_ts,
        "condition_on_previous_text": False,
        "suppress_blank": True,
        "vad_filter": False,
        # Island already isolates speech; keep quiet dialogue.
        "no_speech_threshold": 0.95,
        "log_prob_threshold": -1.6,
        "compression_ratio_threshold": 2.6,
    }
    prompt = str(initial_prompt or "").strip()
    words = str(hotwords or "").strip()
    # anime-whisper: prompts cause hallucinations — normally cleared upstream.
    if prompt:
        transcribe_kw["initial_prompt"] = prompt[:800]
    if words:
        transcribe_kw["hotwords"] = words[:400]

    if requested_beam != 1:
        _log.info(
            "anime-whisper TEN ASR: beam_size forced to 1 (greedy); request had %d",
            requested_beam,
        )
    _log.info(
        "anime-whisper TEN ASR: in-memory PCM slices | no per-frame ffmpeg | "
        "device=%s | beam=%d | frames=%d",
        dev,
        beam,
        len(pieces),
    )

    all_cues: list[dict[str, Any]] = []
    empty_frames = 0
    slice_fails = 0
    ffmpeg_fallback = 0
    log_every = max(1, len(pieces) // 20)
    work: Path | None = None

    def _transcribe_audio(audio_in: Any) -> list[dict[str, Any]]:
        try:
            segments, _info = model.transcribe(audio_in, **transcribe_kw)
        except TypeError:
            kw = dict(transcribe_kw)
            for drop in ("hotwords", "initial_prompt", "hallucination_silence_threshold"):
                kw.pop(drop, None)
            try:
                segments, _info = model.transcribe(audio_in, **kw)
            except TypeError:
                kw.pop("clip_timestamps", None)
                segments, _info = model.transcribe(audio_in, **kw)
        return _cues_from_whisper_segments(segments, include_words=include_words)

    def _ffmpeg_fallback_frame(start: float, end: float, idx: int) -> list[dict[str, Any]]:
        nonlocal work, ffmpeg_fallback
        from ..audio.preprocess import trim_media_window

        if work is None:
            work = Path(tempfile.mkdtemp(prefix="aw_ten_isle_"))
        wav = trim_media_window(
            media_path,
            start_sec=start,
            end_sec=end,
            out_dir=work / f"i{idx:04d}",
        )
        ffmpeg_fallback += 1
        return _transcribe_audio(wav)

    try:
        if on_progress:
            on_progress(
                {
                    "stage": "transcribe",
                    "percent": 12,
                    "detail": f"TEN 人声帧 {len(pieces)} 段 | 逐段 anime-whisper",
                    "processedSec": 0.0,
                    "mediaDurationSec": duration_s if duration_s > 0 else None,
                }
            )
        for i, (start, end) in enumerate(pieces):
            if should_cancel and should_cancel():
                raise RuntimeError("cancelled")
            span = max(0.0, end - start)
            if span < _ANIME_VAD_MIN_ISLAND_S:
                continue
            if on_progress:
                local_pct = asr_local_from_timeline(
                    processed_s=start,
                    duration_s=duration_s if duration_s > 0 else max(end, 1.0),
                    start=15.0,
                    end=92.0,
                )
                detail = f"帧 {i + 1}/{len(pieces)}"
                if duration_s > 0:
                    detail = (
                        f"{format_mmss(start)} / {format_mmss(duration_s)} | "
                        f"帧 {i + 1}/{len(pieces)}"
                    )
                on_progress(
                    {
                        "stage": "transcribe",
                        "percent": int(local_pct),
                        "detail": detail,
                        "processedSec": float(start),
                        "mediaDurationSec": duration_s if duration_s > 0 else None,
                    }
                )
            if i == 0 or i + 1 == len(pieces) or (i + 1) % log_every == 0:
                _log.info(
                    "anime-whisper TEN frame %d/%d: %.2f-%.2fs (%.2fs)",
                    i + 1,
                    len(pieces),
                    start,
                    end,
                    span,
                )

            part: list[dict[str, Any]] = []
            try:
                clip = slice_pcm_f32(audio_f32, start, end, sample_rate=TEN_SR)
                if clip.size < int(0.05 * TEN_SR):
                    raise RuntimeError("PCM slice too short")
                part = _transcribe_audio(clip)
            except Exception as err:
                slice_fails += 1
                _log.warning(
                    "TEN PCM slice ASR failed %s %.2f-%.2fs: %s; trying ffmpeg trim",
                    media_name,
                    start,
                    end,
                    err,
                )
                try:
                    part = _ffmpeg_fallback_frame(start, end, i)
                except Exception as err2:
                    _log.warning(
                        "TEN island ffmpeg fallback failed %s %.2f-%.2fs: %s",
                        media_name,
                        start,
                        end,
                        err2,
                    )
                    continue

            texts = [
                str(c.get("text") or "").strip()
                for c in (part or [])
                if isinstance(c, dict) and str(c.get("text") or "").strip()
            ]
            if not texts:
                empty_frames += 1
                _log.debug(
                    "anime-whisper TEN frame %d/%d empty: %.2f-%.2fs",
                    i + 1,
                    len(pieces),
                    start,
                    end,
                )
                continue
            # VAD frame owns [start,end]; paint text proportionally.
            joined = "".join(texts)
            local = split_frame_text_to_cues(joined, 0.0, span)
            if not local:
                local = repair_collapsed_asr_cues(part or [], media_end_s=span)
                if local and span > 0.25:
                    local = align_text_cues_to_timing(
                        local,
                        [{"start": 0.0, "end": span, "text": "speech"}],
                    )
            shifted = _clamp_cues_to_span(_shift_cues(local, start), start, end)
            if on_cue:
                for cue in shifted:
                    on_cue(cue)
            all_cues.extend(shifted)
            _log.debug(
                "anime-whisper TEN frame %d/%d -> %d cue(s): %s",
                i + 1,
                len(pieces),
                len(shifted),
                (joined[:48] + "...") if len(joined) > 48 else joined,
            )
    finally:
        if work is not None:
            shutil.rmtree(work, ignore_errors=True)
        # Drop large PCM reference promptly after island ASR.
        try:
            del audio_f32
        except Exception:
            pass

    _log.info(
        "anime-whisper TEN path done: %s | decode_mode=pcm_reuse | frames=%d | "
        "cues=%d | empty=%d | slice_fail=%d | ffmpeg_fallback=%d",
        media_name,
        len(pieces),
        len(all_cues),
        empty_frames,
        slice_fails,
        ffmpeg_fallback,
    )
    # Empty list must not count as success — callers use truthiness to fall through
    # to fixed-window ASR (soft-AV mis-threshold VAD can yield frames with no text).
    if not all_cues:
        _log.info(
            "anime-whisper TEN path produced 0 cues for %s "
            "(frames=%d empty=%d slice_fail=%d); returning None for windowed fallback",
            media_name,
            len(pieces),
            empty_frames,
            slice_fails,
        )
        return None
    if on_progress:
        on_progress(
            {
                "stage": "transcribe",
                "percent": 96,
                "detail": f"{len(all_cues)} 条（TEN 逐帧）",
                "processedSec": duration_s if duration_s > 0 else None,
                "mediaDurationSec": duration_s if duration_s > 0 else None,
            }
        )
    return all_cues



def _windowed_whisper_transcribe(
    *,
    media_path: str,
    language: str,
    asr_model: str,
    device: str,
    beam_size: int,
    vad_options: dict[str, Any] | None,
    clip_timestamps: list[dict[str, float]] | list[float] | None,
    force_no_vad: bool,
    initial_prompt: str | None,
    hotwords: str | None,
    on_progress: ProgressCb | None,
    on_cue: CueCb | None,
    should_cancel: Callable[[], bool] | None,
    include_words: bool,
    word_timestamps: bool | None,
    duration_s: float,
    timing_align_model: str | None = None,
) -> list[dict[str, Any]]:
    """Crash-safe path: ffmpeg window extracts + single-pass Whisper per window."""
    from ..audio.preprocess import trim_media_window

    # Prefer TEN island ASR over fixed windows + proportional retime.
    # Default (None/auto) and explicit ten/vad → TEN short frames.
    # timingAlignModel="" / rate / off → skip (caller wants rate-repair only).
    if _anime_uses_ten_island_asr(timing_align_model):
        island = _whisper_anime_ten_island_transcribe(
            media_path=media_path,
            language=language,
            asr_model=asr_model,
            device=device,
            beam_size=beam_size,
            vad_options=vad_options,
            initial_prompt=initial_prompt,
            hotwords=hotwords,
            on_progress=on_progress,
            on_cue=on_cue,
            should_cancel=should_cancel,
            include_words=include_words,
            duration_s=duration_s,
            timing_align_model=timing_align_model,
        )
        if island:
            return island
        _log.info(
            "anime-whisper island VAD path unavailable for %s; using ≤%.0fs windowed + CPS repair",
            Path(media_path).name,
            _WINDOWED_MAX_SPAN_S,
        )

    clips = _normalize_clip_dicts(clip_timestamps)
    # Prefer full-timeline fixed windows whenever VAD clips are absent OR the
    # caller forced no-VAD (anime-whisper soft-AV path). Clips-only packing
    # historically dropped most spoken dialogue between moan islands.
    if force_no_vad or not clips:
        windows = fixed_time_windows(duration_s)
        mode = "fixed"
    else:
        packed = pack_clips_into_windows(clips)
        windows = fill_timeline_gaps(packed, duration_s, max_gap_s=12.0)
        mode = "clips+gaps" if len(windows) > len(packed) else "clips"
    if not windows:
        windows = [{"start": 0.0, "end": max(duration_s, 1.0)}]

    # Timing align after windowed decode:
    # - None / "auto" → already tried TEN above; dual-ASR still opt-in only
    # - "" / rate → disabled (rate-repair only)
    # - whisperx / wav2vec2 → CTC forced align (+ ASR fallback)
    # - whisper-ja-1.5b / turbo → dual ASR timing (explicit)
    # Dual ASR fuzzy match was measured ~35% on soft-AV and left most cues drifted;
    # do not enable it unless the job sets timingAlignModel to an ASR id.
    align_model: str | None
    if timing_align_model is not None and str(timing_align_model).strip() == "":
        align_model = None
        align_disabled = True
    else:
        raw = str(timing_align_model).strip() if timing_align_model is not None else ""
        raw_l = raw.lower()
        if (
            not raw
            or raw_l in (
                "auto",
                "ten",
                "ten-vad",
                "ten_vad",
                "vad",
                "firered",
                "firered-vad",
                "fire-red",
                "fireredvad",
                "off",
                "rate",
                "none",
                "cps",
            )
        ):
            # Island VAD already attempted (or explicitly rate-only). No dual-ASR.
            align_model = None
            align_disabled = True
        else:
            align_model = raw
            align_disabled = False

    if on_progress:
        mode_label = {
            "clips": "VAD切片",
            "clips+gaps": "VAD+空隙补窗",
            "fixed": "定长全片",
        }.get(mode, mode)
        align_note = ""
        if align_model:
            al = str(align_model).lower()
            if al in ("ten", "ten-vad", "ten_vad", "vad"):
                align_note = " | 对时 TEN VAD"
            elif al in ("auto",):
                align_note = " | 对时 ja-1.5b 模糊匹配"
            elif al in ("whisperx", "wav2vec2", "wav2vec", "w2v"):
                align_note = " | 对时 WhisperX/wav2vec2"
            else:
                align_note = f" | 对时 {align_model}"
        on_progress(
            {
                "stage": "transcribe",
                "percent": 12,
                "detail": (
                    f"{asr_model} 自动分窗 | {len(windows)} 段"
                    f"（{mode_label}）{align_note}"
                ),
                "mediaDurationSec": duration_s if duration_s > 0 else None,
            }
        )

    work = Path(tempfile.mkdtemp(prefix="transub_awin_"))
    all_cues: list[dict[str, Any]] = []
    try:
        for i, win in enumerate(windows):
            if should_cancel and should_cancel():
                raise RuntimeError("cancelled")
            start = max(0.0, float(win["start"]) - _WINDOWED_PAD_S)
            end = float(win["end"]) + _WINDOWED_PAD_S
            if duration_s > 0:
                end = min(end, duration_s)
            if end <= start + 0.05:
                continue
            if on_progress:
                local = 15.0 + 75.0 * (i / max(len(windows), 1))
                detail = (
                    f"分段 {i + 1}/{len(windows)} "
                    f"({win['start']:.0f}-{win['end']:.0f}s)"
                )
                if align_model:
                    detail += " | 识别+对时"
                on_progress(
                    {
                        "stage": "transcribe",
                        "percent": int(local),
                        "detail": detail,
                        "processedSec": float(win["start"]),
                        "mediaDurationSec": duration_s if duration_s > 0 else None,
                    }
                )
            try:
                wav = trim_media_window(
                    media_path,
                    start_sec=start,
                    end_sec=end,
                    out_dir=work / f"w{i:04d}",
                )
            except Exception as err:
                _log.warning("anime-whisper window trim failed %s: %s", win, err)
                continue
            # Never pass clip_timestamps into the CT2 call — that path also
            # native-crashes on this model. Window already isolates speech.
            # DTW word timestamps + hallucination_silence_threshold also trip
            # ACCESS_VIOLATION on this CT2 build — keep the call minimal.
            safe_vad = dict(vad_options or {})
            safe_vad.pop("hallucinationSilenceThreshold", None)
            safe_vad["hallucinationSilenceThreshold"] = 0
            part = whisper_transcribe(
                media_path=wav,
                language=language,
                asr_model=asr_model,
                device=device,
                beam_size=beam_size,
                vad_options=safe_vad,
                clip_timestamps=None,
                force_no_vad=True,
                initial_prompt=initial_prompt,
                hotwords=hotwords,
                on_progress=None,
                on_cue=None,
                should_cancel=should_cancel,
                include_words=include_words,
                word_timestamps=True if include_words else False,
                _allow_windowed=False,
                timing_align_model="",  # outer window loop owns align
            )
            shifted = _shift_cues(part or [], start)
            # Repair before on_cue / quality filters (collapsed TS → CPS drop).
            shifted = repair_collapsed_asr_cues(shifted, media_end_s=end)
            if align_model and not align_disabled:
                # Align on the window wav (local times), then shift.
                local_cues = _shift_cues(shifted, -start)
                aligned_local = resolve_and_align_window_cues(
                    local_cues,
                    media_path=wav,
                    language=language,
                    device=device,
                    beam_size=beam_size,
                    vad_options=safe_vad,
                    timing_model=align_model,
                    should_cancel=should_cancel,
                    media_end_s=max(0.0, end - start),
                )
                shifted = _shift_cues(aligned_local, start)
            if on_cue:
                for cue in shifted:
                    on_cue(cue)
            all_cues.extend(shifted)
    finally:
        shutil.rmtree(work, ignore_errors=True)

    if on_progress:
        on_progress(
            {
                "stage": "transcribe",
                "percent": 96,
                "detail": f"{len(all_cues)} 条（分段"
                + (f"+{align_model}对时" if align_model else "")
                + "）",
                "processedSec": duration_s if duration_s > 0 else None,
                "mediaDurationSec": duration_s if duration_s > 0 else None,
            }
        )
    return all_cues


def whisper_transcribe(
    *,
    media_path: str,
    language: str = "auto",
    asr_model: str = "whisper-large-v3-turbo",
    device: str = "auto",
    beam_size: int = 5,
    vad_options: dict[str, Any] | None = None,
    clip_timestamps: list[dict[str, float]] | list[float] | None = None,
    force_no_vad: bool = False,
    initial_prompt: str | None = None,
    hotwords: str | None = None,
    on_progress: ProgressCb | None = None,
    on_cue: CueCb | None = None,
    should_cancel: Callable[[], bool] | None = None,
    include_words: bool = False,
    word_timestamps: bool | None = None,
    _allow_windowed: bool = True,
    timing_align_model: str | None = None,
) -> list[dict[str, Any]]:
    from .whisper_av_shim import import_whisper_model_class, sac_policy_hint
    from ..models_catalog import (
        asr_is_anime_whisper,
        asr_needs_windowed_transcribe,
        asr_skips_whisper_prompt,
    )

    try:
        WhisperModel, used_ffmpeg_audio = import_whisper_model_class()
    except RuntimeError:
        raise
    except Exception as err:
        raise RuntimeError(
            "无法加载 Whisper。"
            f" {sac_policy_hint()} 原始错误: {err}"
        ) from err

    if not is_model_installed(asr_model):
        raise RuntimeError(f"ASR model not installed: {asr_model}. Run models download first.")

    # anime-whisper: never feed prompts (hallucinates hard).
    if asr_skips_whisper_prompt(asr_model):
        initial_prompt = None
        hotwords = None

    model_dir = str(model_local_path(asr_model))
    try:
        from ..runtime_gpu import inject_nvidia_lib_path

        inject_nvidia_lib_path()
    except Exception:
        pass
    requested = str(device or "auto").strip().lower()
    dev = resolve_ctranslate2_device(requested)
    compute = "float16" if dev == "cuda" else "int8"
    beam = max(1, min(20, int(beam_size or 5)))
    # DTW word alignment tightens cue bounds but is expensive; required when
    # exporting word/karaoke timings. Default True for quality; callers can
    # pass False for speed profiles.
    # anime/kotoba CT2: DTW word timestamps → ACCESS_VIOLATION (0xC0000005).
    if asr_needs_windowed_transcribe(asr_model) and not include_words:
        use_word_ts = False if word_timestamps is None else bool(word_timestamps)
    else:
        use_word_ts = True if include_words else (True if word_timestamps is None else bool(word_timestamps))

    from ..vad import normalize_vad_options, whisper_vad_kwargs

    vad_opts = normalize_vad_options(vad_options if isinstance(vad_options, dict) else {})
    # Fragile CT2 builds: hallucination_silence_threshold can native-crash.
    if asr_needs_windowed_transcribe(asr_model):
        vad_opts = {**vad_opts, "hallucinationSilenceThreshold": 0}
    # External clips / failover: never re-filter with built-in Silero.
    use_external_clips = bool(clip_timestamps) or force_no_vad
    if use_external_clips:
        vad_kw: dict[str, Any] = {"vad_filter": False}
    else:
        vad_kw = whisper_vad_kwargs(vad_opts)
    duration_s = _probe_duration_s(media_path)

    # TEN islands → anime-whisper per island (any duration).
    # Avoids proportional remapping that parks later lines in early islands.
    ten_island_attempted = False
    if (
        _allow_windowed
        and asr_is_anime_whisper(asr_model)
        and _anime_uses_ten_island_asr(timing_align_model)
        and not clip_timestamps
    ):
        ten_island_attempted = True
        _log.info(
            "anime-whisper timing: island VAD short frames (align=%s)",
            timing_align_model if timing_align_model is not None else "auto",
        )
        island = _whisper_anime_ten_island_transcribe(
            media_path=media_path,
            language=language,
            asr_model=asr_model,
            device=device,
            beam_size=beam_size,
            vad_options=vad_options,
            initial_prompt=initial_prompt,
            hotwords=hotwords,
            on_progress=on_progress,
            on_cue=on_cue,
            should_cancel=should_cancel,
            include_words=include_words,
            duration_s=duration_s,
            timing_align_model=timing_align_model,
        )
        if island:
            _log.info(
                "anime-whisper island VAD path returned %d cues for %s",
                len(island),
                Path(media_path).name,
            )
            return island
        _log.info(
            "anime-whisper island VAD path returned None for %s; continuing to windowed path",
            Path(media_path).name,
        )

    # Long-media auto-window for models that native-crash on single-pass CT2.
    # Never fall through to full-file CT2 when duration probe failed — that path
    # ACCESS_VIOLATION-crashes and can leave a 1-cue streaming stub on disk.
    if _allow_windowed and asr_needs_windowed_transcribe(asr_model):
        if duration_s <= 0 and not clip_timestamps:
            raise RuntimeError(
                f"无法读取媒体时长（{media_path}），{asr_model} 不能安全全片直跑。"
                "请确认 ffmpeg/ffprobe 可用后重试。"
            )
        if bool(clip_timestamps) or duration_s > _WINDOWED_MAX_SPAN_S + 1.0:
            # Skip re-entering TEN inside windowed after the outer attempt already ran.
            win_align = "" if ten_island_attempted else timing_align_model
            return _windowed_whisper_transcribe(
                media_path=media_path,
                language=language,
                asr_model=asr_model,
                device=device,
                beam_size=beam_size,
                vad_options=vad_options,
                clip_timestamps=clip_timestamps,
                force_no_vad=force_no_vad,
                initial_prompt=initial_prompt,
                hotwords=hotwords,
                on_progress=on_progress,
                on_cue=on_cue,
                should_cancel=should_cancel,
                include_words=include_words,
                word_timestamps=word_timestamps,
                duration_s=duration_s,
                timing_align_model=win_align,
            )

    flat_clips: list[float] | None = None
    if clip_timestamps:
        flat_clips = []
        if clip_timestamps and isinstance(clip_timestamps[0], dict):
            for c in clip_timestamps:  # type: ignore[assignment]
                flat_clips.append(float(c["start"]))  # type: ignore[index]
                flat_clips.append(float(c["end"]))  # type: ignore[index]
        else:
            flat_clips = [float(x) for x in clip_timestamps]  # type: ignore[arg-type]

    cache_key = f"{model_dir}|{dev}|{compute}"
    if on_progress:
        detail = f"加载 Whisper（{dev}）"
        if used_ffmpeg_audio:
            detail += " | 音频解码改用 ffmpeg（PyAV 被系统策略拦截）"
        if requested in ("auto", "cuda") and dev == "cpu":
            detail += " | 未找到 cublas64_12.dll，已回退 CPU"
        if flat_clips:
            detail += f" | 外部片段 {len(flat_clips) // 2} 个"
        elif force_no_vad:
            detail += " | VAD 回退（全片音频）"
        if cache_key in _MODEL_CACHE:
            detail += " | 已缓存"
        on_progress(
            {
                "stage": "model",
                "percent": 5,
                "detail": detail,
                "mediaDurationSec": duration_s if duration_s > 0 else None,
            }
        )

    def _run(active_device: str, active_compute: str) -> list[dict[str, Any]]:
        model = _get_cached_whisper_model(
            WhisperModel,
            model_dir,
            device=active_device,
            compute_type=active_compute,
        )
        lang = None if not language or language == "auto" else language

        if on_progress:
            on_progress(
                {
                    "stage": "transcribe",
                    "percent": 15,
                    "detail": f"转写中（{active_device}）",
                    "processedSec": 0.0,
                    "mediaDurationSec": duration_s if duration_s > 0 else None,
                }
            )

        # word_timestamps: DTW alignment for tighter cue bounds (esp. turbo).
        # condition_on_previous_text=False: reduces long-form drift / hallucination cascade.
        transcribe_kw: dict[str, Any] = {
            "language": lang,
            "beam_size": beam,
            "word_timestamps": use_word_ts,
            "condition_on_previous_text": False,
            "suppress_blank": True,
            **vad_kw,
        }
        prompt = str(initial_prompt or "").strip()
        words = str(hotwords or "").strip()
        # Prefer initial_prompt for JA cast names; hotwords alone can over-trigger
        # on some faster-whisper builds. Pass both when both set.
        if prompt:
            transcribe_kw["initial_prompt"] = prompt[:800]
        if words:
            transcribe_kw["hotwords"] = words[:400]
        if flat_clips:
            transcribe_kw["clip_timestamps"] = flat_clips
        lang_l = str(lang or "").strip().lower()
        ja_mode = lang_l in ("ja", "japanese", "jp")
        film_mode = bool(vad_opts.get("filmPreset"))
        # Soft dialogue: raise no_speech when sensitive or using WhisperSeg clips.
        # Higher no_speech / lower log_prob = keep more breathy speech & moans
        # (Whisper often scores them as "non-speech").
        sensitive_mode = bool(vad_opts.get("sensitive") or flat_clips)
        # anime-whisper window extracts: force high-recall blanking (windows already
        # isolate audio; do not treat quiet dialogue as non-speech).
        from ..models_catalog import asr_needs_windowed_transcribe as _needs_win

        if _needs_win(asr_model) and force_no_vad and not flat_clips:
            transcribe_kw["no_speech_threshold"] = 0.95
            transcribe_kw["log_prob_threshold"] = -1.6
            if ja_mode:
                transcribe_kw["compression_ratio_threshold"] = 2.6
        elif film_mode and not sensitive_mode:
            # Film / BGM: stricter blanking so music beds don't emit "." cues.
            transcribe_kw["no_speech_threshold"] = 0.5
            transcribe_kw["log_prob_threshold"] = -0.85
        elif sensitive_mode:
            if ja_mode and flat_clips:
                # Prefer recall on JA AV soft scenes; blank gaps still gated
                # via compression_ratio + post quality filters.
                transcribe_kw["no_speech_threshold"] = 0.82
                transcribe_kw["log_prob_threshold"] = -1.6
            else:
                transcribe_kw["no_speech_threshold"] = 0.72 if flat_clips else 0.95
                transcribe_kw["log_prob_threshold"] = -1.5
        elif ja_mode:
            # JA without external VAD: mild blank suppression (AV soft speech).
            transcribe_kw["no_speech_threshold"] = 0.6
            transcribe_kw["log_prob_threshold"] = -1.0
        # JA: mild compression gate. Too tight (≤2.2) drops real moan loops
        # that look like decoder repeats; keep 2.6 for soft-scene recall.
        if ja_mode and "compression_ratio_threshold" not in transcribe_kw:
            transcribe_kw["compression_ratio_threshold"] = 2.6 if sensitive_mode else 2.4
        hallu = vad_opts.get("hallucinationSilenceThreshold")
        if hallu is None and film_mode:
            hallu = 2.0
        if hallu is None and ja_mode and not sensitive_mode:
            # Only default-clamp non-sensitive JA; soft/WhisperSeg gaps often
            # hold quiet dialogue after >2s silence — do not auto-skip those.
            hallu = 2.0
        if hallu is not None and float(hallu) > 0:
            try:
                segments, _info = model.transcribe(
                    media_path,
                    hallucination_silence_threshold=float(hallu),
                    **transcribe_kw,
                )
            except TypeError:
                # Older builds may reject hotwords / hallucination kw
                for drop in ("hotwords", "initial_prompt", "hallucination_silence_threshold"):
                    transcribe_kw.pop(drop, None)
                try:
                    segments, _info = model.transcribe(media_path, **transcribe_kw)
                except TypeError:
                    transcribe_kw.pop("clip_timestamps", None)
                    segments, _info = model.transcribe(media_path, **transcribe_kw)
        else:
            try:
                segments, _info = model.transcribe(media_path, **transcribe_kw)
            except TypeError:
                # Older faster-whisper without clip_timestamps / hotwords
                for drop in ("hotwords", "initial_prompt", "clip_timestamps"):
                    transcribe_kw.pop(drop, None)
                segments, _info = model.transcribe(media_path, **transcribe_kw)

        last_emit = 0.0
        buffered: list[Any] = []
        cues_out: list[dict[str, Any]] = []
        for seg in segments:
            if should_cancel and should_cancel():
                raise RuntimeError("cancelled")
            buffered.append(seg)
            if on_cue:
                for cue in _cues_from_whisper_segments([seg], include_words=include_words):
                    on_cue(cue)
                    cues_out.append(cue)
            end_s = float(getattr(seg, "end", 0) or 0)
            if on_progress and (end_s - last_emit >= 2.0 or len(buffered) % 8 == 0):
                last_emit = end_s
                local = asr_local_from_timeline(
                    processed_s=end_s,
                    duration_s=duration_s if duration_s > 0 else max(end_s, 1.0),
                    start=15.0,
                    end=90.0,
                )
                detail = f"{len(buffered)} 段"
                if duration_s > 0:
                    detail = f"{format_mmss(end_s)} / {format_mmss(duration_s)} | {len(buffered)} 段"
                on_progress(
                    {
                        "stage": "transcribe",
                        "percent": int(local),
                        "detail": detail,
                        "processedSec": end_s,
                        "mediaDurationSec": duration_s if duration_s > 0 else end_s,
                    }
                )
        if on_cue:
            return cues_out
        return _cues_from_whisper_segments(buffered, include_words=include_words)

    try:
        cues = _run(dev, compute)
    except Exception as err:
        if dev == "cuda" and is_cublas_missing_error(err):
            if on_progress:
                on_progress(
                    {
                        "stage": "model",
                        "percent": 8,
                        "detail": "CUDA cuBLAS 不可用，改用 CPU 重试…",
                    }
                )
            cues = _run("cpu", "int8")
        else:
            if is_cublas_missing_error(err):
                raise RuntimeError(
                    "缺少 CUDA 12 运行库 cublas64_12.dll（faster-whisper/CTranslate2 需要）。"
                    "可在设置中将推理设备改为 CPU，或安装 CUDA Toolkit 12 并将其 bin 加入 PATH 后重试。"
                ) from err
            raise

    # Keep cached models resident; only trim Python refs lightly.
    try:
        import gc

        gc.collect()
    except Exception:
        pass

    # anime-whisper (and similar CT2 builds): fix collapsed segment timestamps
    # before jobs.py ja_av CPS hallucination cleanup deletes the dialogue.
    from ..models_catalog import asr_needs_collapsed_ts_repair

    if asr_needs_collapsed_ts_repair(asr_model):
        cues = repair_collapsed_asr_cues(
            cues,
            media_end_s=duration_s if duration_s > 0 else None,
        )
        # Dual-model align is opt-in only (explicit timingAlignModel).
        raw_align = (
            str(timing_align_model).strip()
            if timing_align_model is not None
            else ""
        )
        if raw_align and raw_align.lower() != "auto":
            cues = resolve_and_align_window_cues(
                cues,
                media_path=media_path,
                language=language,
                device=device,
                beam_size=beam_size,
                vad_options=vad_options,
                timing_model=raw_align,
                should_cancel=should_cancel,
                media_end_s=duration_s if duration_s > 0 else None,
            )

    if on_progress:
        on_progress(
            {
                "stage": "transcribe",
                "percent": 96,
                "detail": f"{len(cues)} 条",
                "processedSec": duration_s if duration_s > 0 else None,
                "mediaDurationSec": duration_s if duration_s > 0 else None,
            }
        )
    return cues


_LID_MODEL_CANDIDATES = (
    "whisper-tiny",
    "whisper-large-v3-turbo",
    "whisper-ja-1.5b",
    "anime-whisper",
    "whisper-large-v2",
    "whisper-large-v3",
)


def resolve_whisper_model_for_lid(preferred: str | None = None) -> str | None:
    """Pick an installed Whisper CT2 model for short-window language detection."""
    ordered: list[str] = []
    pref = str(preferred or "").strip()
    if pref and "whisper" in pref.lower() and "sensevoice" not in pref.lower():
        ordered.append(pref)
    for mid in _LID_MODEL_CANDIDATES:
        if mid not in ordered:
            ordered.append(mid)
    for mid in ordered:
        try:
            if is_model_installed(mid):
                return mid
        except Exception:
            continue
    return None


def detect_language_short(
    media_path: str,
    *,
    asr_model: str | None = None,
    device: str = "auto",
    duration_sec: float = 12.0,
    start_sec: float = 0.0,
) -> dict[str, Any]:
    """
    Detect spoken language from a short audio window (Whisper encoder only).

    Prefers an ffmpeg-trimmed window so long media need not be fully decoded.
    ``start_sec`` skips opening titles/BGM (desktop auto-sense typically ~60s+).
    Falls back to the file head when the seek window is empty or past EOF.
    """
    path = Path(str(media_path or "")).expanduser()
    if not path.exists():
        raise FileNotFoundError(f"media not found: {path}")

    model_id = resolve_whisper_model_for_lid(asr_model)
    if not model_id:
        raise RuntimeError(
            "未安装可用的 Whisper 模型（如 whisper-tiny / whisper-large-v3-turbo），无法短窗语种探测"
        )

    # Dist may ship weights without pip extras; install faster-whisper + numpy on first LID.
    try:
        from ..runtime_extras import ensure_asr_whisper

        ensured = ensure_asr_whisper()
        if not ensured.get("ok"):
            raise RuntimeError(
                ensured.get("message")
                or "未安装 Whisper 运行库（faster-whisper / numpy），无法短窗语种探测"
            )
    except ImportError:
        pass

    from .whisper_av_shim import import_whisper_model_class, sac_policy_hint

    try:
        WhisperModel, _used_ffmpeg_audio = import_whisper_model_class()
    except Exception as err:
        raise RuntimeError(
            f"无法加载 Whisper。{sac_policy_hint()} 原始错误: {err}"
        ) from err

    try:
        from ..runtime_gpu import inject_nvidia_lib_path

        inject_nvidia_lib_path()
    except Exception:
        pass

    model_dir = str(model_local_path(model_id))
    requested = str(device or "auto").strip().lower()
    dev = resolve_ctranslate2_device(requested)
    compute = "float16" if dev == "cuda" else "int8"
    max_sec = max(3.0, min(30.0, float(duration_sec or 12.0)))
    want_start = max(0.0, float(start_sec or 0.0))

    def _load_window(sr: int) -> tuple[Any, float]:
        """Return (audio_float32, used_start_sec)."""
        from faster_whisper.audio import decode_audio

        min_samples = int(sr * 2.0)
        max_samples = int(sr * max_sec)

        def _decode_path(src: str, slice_start: float = 0.0) -> Any:
            audio = decode_audio(str(src), sampling_rate=sr)
            if audio is None or len(audio) == 0:
                return None
            if slice_start > 0:
                start_i = int(sr * slice_start)
                if len(audio) <= start_i + min_samples:
                    return None
                audio = audio[start_i : start_i + max_samples]
            elif len(audio) > max_samples:
                audio = audio[:max_samples]
            return audio

        # Fast path: ffmpeg seek + short extract (avoids decoding whole file)
        if want_start > 0.05:
            try:
                from ..audio.preprocess import trim_media_window

                trimmed = trim_media_window(
                    str(path),
                    start_sec=want_start,
                    duration_sec=max_sec,
                )
                try:
                    audio = _decode_path(trimmed)
                    if audio is not None and len(audio) >= min_samples:
                        return audio, want_start
                finally:
                    try:
                        Path(trimmed).unlink(missing_ok=True)
                    except OSError:
                        pass
                    try:
                        Path(trimmed).parent.rmdir()
                    except OSError:
                        pass
            except Exception:
                pass

        # In-memory slice, then fall back to file head
        audio = _decode_path(str(path), want_start if want_start > 0.05 else 0.0)
        if audio is not None and len(audio) >= min_samples:
            return audio, want_start if want_start > 0.05 else 0.0
        audio = _decode_path(str(path), 0.0)
        if audio is None or len(audio) == 0:
            raise RuntimeError("无法解码音频用于语种探测")
        return audio, 0.0

    def _run(active_device: str, active_compute: str) -> dict[str, Any]:
        model = _get_cached_whisper_model(
            WhisperModel,
            model_dir,
            device=active_device,
            compute_type=active_compute,
        )
        sr = int(getattr(model.feature_extractor, "sampling_rate", 16000) or 16000)
        audio, used_start = _load_window(sr)

        language, probability, all_probs = model.detect_language(
            audio,
            language_detection_segments=1,
            language_detection_threshold=0.45,
        )
        top: list[dict[str, Any]] = []
        if isinstance(all_probs, list):
            for row in all_probs[:5]:
                if isinstance(row, (list, tuple)) and len(row) >= 2:
                    top.append({"language": str(row[0]), "probability": float(row[1])})
                elif isinstance(row, dict):
                    top.append(
                        {
                            "language": str(row.get("language") or row.get("lang") or ""),
                            "probability": float(row.get("probability") or row.get("prob") or 0),
                        }
                    )
        return {
            "ok": True,
            "language": str(language or "").strip().lower() or "auto",
            "confidence": float(probability or 0),
            "asrModel": model_id,
            "device": active_device,
            "durationSec": max_sec,
            "startSec": round(float(used_start), 1),
            "top": top,
        }

    try:
        return _run(dev, compute)
    except Exception as err:
        if dev == "cuda" and is_cublas_missing_error(err):
            return _run("cpu", "int8")
        raise
